UPDATE autoops_core.library_items SET definition='{"name": "Incident Postmortem Writer", "description": "Turns a raw incident timeline into a structured post-incident review \\u2014 impact, timeline, root cause, and follow-up actions.", "inputs": [{"variable": "incident_notes", "label": "Incident notes or timeline", "type": "paragraph", "required": true, "maxLength": 8000, "hint": "Paste the Slack thread, ticket updates or your own rough notes."}, {"variable": "severity", "label": "Severity", "type": "select", "required": true, "default": "P1", "options": ["P1", "P2", "P3", "P4"], "maxLength": 64}, {"variable": "audience", "label": "Written for", "type": "select", "required": true, "default": "Internal engineering", "options": ["Internal engineering", "Customer-facing"], "maxLength": 64}, {"variable": "service_name", "label": "Affected service", "type": "text", "required": false, "maxLength": 500, "hint": "Example: Payments API"}], "nodes": [{"id": "start", "type": "start", "title": "Start"}, {"id": "writer", "type": "llm", "title": "Postmortem Writer", "prompt": [{"role": "system", "text": "You write post-incident reviews for a managed-services provider. Your reader is deciding what to fix, so the document has to be honest about what is known and what is not.\\n\\nProduce markdown with these sections, in this order:\\n1. Summary \\u2014 two sentences: what broke, who was affected, how long.\\n2. Impact \\u2014 who or what was affected, and for how long.\\n3. Timeline \\u2014 a table of time, event, source. Use only times present in the notes.\\n4. Root cause \\u2014 what actually caused it.\\n5. Contributing factors \\u2014 what made it worse or slower to detect.\\n6. What went well \\u2014 genuinely, not filler.\\n7. Action items \\u2014 a table of action, owner, priority. One action per row.\\n\\nRULES YOU MUST NOT BREAK:\\n- Never invent a root cause. If the notes do not establish one, write \'Root cause not established from the available timeline\' and say precisely what evidence would settle it. A plausible-sounding invented cause is the single most damaging thing this document can contain.\\n- Never invent a timestamp, a metric, a customer count or a duration. If the notes do not give it, say it was not recorded.\\n- Never assign an action to a named person the notes do not name. Use \'Owner not assigned\'.\\n- Blameless: describe what the system allowed, not who erred.\\n\\nIf written for a CUSTOMER: no internal hostnames, no employee names, no internal tooling. Lead with impact and remediation, and be plain about what you are still investigating.\\nIf written for INTERNAL ENGINEERING: full technical detail, and name the specific systems involved."}, {"role": "user", "text": "Severity: {{#start.severity#}}\\nAffected service: {{#start.service_name#}}\\nWritten for: {{#start.audience#}}\\n\\nIncident notes:\\n{{#start.incident_notes#}}"}], "temperature": 0.2}, {"id": "end", "type": "end", "title": "End", "outputs": [{"variable": "final_report", "from": "{{#writer.text#}}"}]}], "edges": [{"source": "start", "target": "writer"}, {"source": "writer", "target": "end"}]}' WHERE tenant_id IS NULL AND title='Incident Postmortem Writer';
UPDATE autoops_workflow.workflows SET definition='{"name": "Incident Postmortem Writer", "description": "Turns a raw incident timeline into a structured post-incident review \\u2014 impact, timeline, root cause, and follow-up actions.", "inputs": [{"variable": "incident_notes", "label": "Incident notes or timeline", "type": "paragraph", "required": true, "maxLength": 8000, "hint": "Paste the Slack thread, ticket updates or your own rough notes."}, {"variable": "severity", "label": "Severity", "type": "select", "required": true, "default": "P1", "options": ["P1", "P2", "P3", "P4"], "maxLength": 64}, {"variable": "audience", "label": "Written for", "type": "select", "required": true, "default": "Internal engineering", "options": ["Internal engineering", "Customer-facing"], "maxLength": 64}, {"variable": "service_name", "label": "Affected service", "type": "text", "required": false, "maxLength": 500, "hint": "Example: Payments API"}], "nodes": [{"id": "start", "type": "start", "title": "Start"}, {"id": "writer", "type": "llm", "title": "Postmortem Writer", "prompt": [{"role": "system", "text": "You write post-incident reviews for a managed-services provider. Your reader is deciding what to fix, so the document has to be honest about what is known and what is not.\\n\\nProduce markdown with these sections, in this order:\\n1. Summary \\u2014 two sentences: what broke, who was affected, how long.\\n2. Impact \\u2014 who or what was affected, and for how long.\\n3. Timeline \\u2014 a table of time, event, source. Use only times present in the notes.\\n4. Root cause \\u2014 what actually caused it.\\n5. Contributing factors \\u2014 what made it worse or slower to detect.\\n6. What went well \\u2014 genuinely, not filler.\\n7. Action items \\u2014 a table of action, owner, priority. One action per row.\\n\\nRULES YOU MUST NOT BREAK:\\n- Never invent a root cause. If the notes do not establish one, write \'Root cause not established from the available timeline\' and say precisely what evidence would settle it. A plausible-sounding invented cause is the single most damaging thing this document can contain.\\n- Never invent a timestamp, a metric, a customer count or a duration. If the notes do not give it, say it was not recorded.\\n- Never assign an action to a named person the notes do not name. Use \'Owner not assigned\'.\\n- Blameless: describe what the system allowed, not who erred.\\n\\nIf written for a CUSTOMER: no internal hostnames, no employee names, no internal tooling. Lead with impact and remediation, and be plain about what you are still investigating.\\nIf written for INTERNAL ENGINEERING: full technical detail, and name the specific systems involved."}, {"role": "user", "text": "Severity: {{#start.severity#}}\\nAffected service: {{#start.service_name#}}\\nWritten for: {{#start.audience#}}\\n\\nIncident notes:\\n{{#start.incident_notes#}}"}], "temperature": 0.2}, {"id": "end", "type": "end", "title": "End", "outputs": [{"variable": "final_report", "from": "{{#writer.text#}}"}]}], "edges": [{"source": "start", "target": "writer"}, {"source": "writer", "target": "end"}]}', node_count=3 WHERE name='Incident Postmortem Writer';
UPDATE autoops_core.library_items SET definition='{"name": "Meeting Actions and Follow-up", "description": "Turns raw meeting notes into an owner-and-action table plus a ready-to-send follow-up email.", "inputs": [{"variable": "notes", "label": "Meeting notes", "type": "paragraph", "required": true, "maxLength": 8000, "hint": "Paste your raw notes. Bullet points and half-sentences are fine."}, {"variable": "meeting_context", "label": "Meeting and attendees", "type": "text", "required": false, "maxLength": 500, "hint": "Example: Weekly delivery sync \\u2014 Ashish, Priya, client PM"}, {"variable": "tone", "label": "Email tone", "type": "select", "required": true, "default": "Direct", "options": ["Direct", "Formal", "Friendly"], "maxLength": 64}], "nodes": [{"id": "start", "type": "start", "title": "Start"}, {"id": "writer", "type": "llm", "title": "Actions and Email Writer", "prompt": [{"role": "system", "text": "You turn messy meeting notes into something people can act on. Output markdown with exactly three sections:\\n\\n## Decisions\\nBullets. Only decisions actually made. If none were, say \'No decisions were recorded.\'\\n\\n## Actions\\nA table: Action | Owner | Due. One action per row, each starting with a verb.\\n\\n## Follow-up email\\nA complete email \\u2014 subject line and body \\u2014 that could be sent without editing.\\n\\nRULES YOU MUST NOT BREAK:\\n- EVERY action needs an owner. If the notes do not name one, write \'Owner not assigned\' \\u2014 never guess, and never quietly assign it to whoever spoke last. An unassigned action that is visible gets picked up; one assigned to the wrong person gets ignored by both of them.\\n- Never invent a due date. If none was given, write \'Not set\'.\\n- Never invent an attendee, a commitment or a number.\\n- Do not pad. Six real actions beat twelve where half were never agreed.\\n- Keep the email under 200 words. Nobody reads a long follow-up.\\n\\nIf anything important was clearly left unresolved, add one line at the very end beginning \'Unresolved:\' \\u2014 that is usually the most valuable sentence in the document."}, {"role": "user", "text": "Meeting: {{#start.meeting_context#}}\\nEmail tone: {{#start.tone#}}\\n\\nNotes:\\n{{#start.notes#}}"}], "temperature": 0.2}, {"id": "end", "type": "end", "title": "End", "outputs": [{"variable": "final_report", "from": "{{#writer.text#}}"}]}], "edges": [{"source": "start", "target": "writer"}, {"source": "writer", "target": "end"}]}' WHERE tenant_id IS NULL AND title='Meeting Actions and Follow-up';
UPDATE autoops_workflow.workflows SET definition='{"name": "Meeting Actions and Follow-up", "description": "Turns raw meeting notes into an owner-and-action table plus a ready-to-send follow-up email.", "inputs": [{"variable": "notes", "label": "Meeting notes", "type": "paragraph", "required": true, "maxLength": 8000, "hint": "Paste your raw notes. Bullet points and half-sentences are fine."}, {"variable": "meeting_context", "label": "Meeting and attendees", "type": "text", "required": false, "maxLength": 500, "hint": "Example: Weekly delivery sync \\u2014 Ashish, Priya, client PM"}, {"variable": "tone", "label": "Email tone", "type": "select", "required": true, "default": "Direct", "options": ["Direct", "Formal", "Friendly"], "maxLength": 64}], "nodes": [{"id": "start", "type": "start", "title": "Start"}, {"id": "writer", "type": "llm", "title": "Actions and Email Writer", "prompt": [{"role": "system", "text": "You turn messy meeting notes into something people can act on. Output markdown with exactly three sections:\\n\\n## Decisions\\nBullets. Only decisions actually made. If none were, say \'No decisions were recorded.\'\\n\\n## Actions\\nA table: Action | Owner | Due. One action per row, each starting with a verb.\\n\\n## Follow-up email\\nA complete email \\u2014 subject line and body \\u2014 that could be sent without editing.\\n\\nRULES YOU MUST NOT BREAK:\\n- EVERY action needs an owner. If the notes do not name one, write \'Owner not assigned\' \\u2014 never guess, and never quietly assign it to whoever spoke last. An unassigned action that is visible gets picked up; one assigned to the wrong person gets ignored by both of them.\\n- Never invent a due date. If none was given, write \'Not set\'.\\n- Never invent an attendee, a commitment or a number.\\n- Do not pad. Six real actions beat twelve where half were never agreed.\\n- Keep the email under 200 words. Nobody reads a long follow-up.\\n\\nIf anything important was clearly left unresolved, add one line at the very end beginning \'Unresolved:\' \\u2014 that is usually the most valuable sentence in the document."}, {"role": "user", "text": "Meeting: {{#start.meeting_context#}}\\nEmail tone: {{#start.tone#}}\\n\\nNotes:\\n{{#start.notes#}}"}], "temperature": 0.2}, {"id": "end", "type": "end", "title": "End", "outputs": [{"variable": "final_report", "from": "{{#writer.text#}}"}]}], "edges": [{"source": "start", "target": "writer"}, {"source": "writer", "target": "end"}]}', node_count=3 WHERE name='Meeting Actions and Follow-up';
DELETE FROM autoops_core.library_items WHERE definition LIKE '%difyWorkflow%';
DELETE FROM autoops_workflow.workflows WHERE definition LIKE '%difyWorkflow%';
SELECT 'remaining-dify-rows' AS check_name, (SELECT COUNT(*) FROM autoops_core.library_items WHERE definition LIKE '%difyWorkflow%') + (SELECT COUNT(*) FROM autoops_workflow.workflows WHERE definition LIKE '%difyWorkflow%') AS n;
SELECT id, name, node_count FROM autoops_workflow.workflows ORDER BY id;
